class PrepareChunksThread:
    def __init__(self, max_pre_download: int):
        self._to_download_queue = Queue()
        self._max_pre_download = max_pre_download
        self._pre_download_counter = 0

    def download(self, chunk_indexes: List[int]) -> None:
        for chunk_index in chunk_indexes:
            if self._pre_download_counter < self._max_pre_download:
                self._to_download_queue.put(chunk_index)
                self._pre_download_counter += 1
            else:
                time.sleep(0.1)  # Wait for 0.1 seconds before checking again

    def start_download(self):
        # Start the download thread
        t = Thread(target=self._download_worker)
        t.start()

    def _download_worker(self):
        while True:
            chunk_index = self._to_download_queue.get()
            # Perform the download
