class SearchEngine:
    def __init__(self, documents: dict[str, str], number_of_documents: int, k1: float = 1.2, b: float = 0.75):
        self._documents = documents
        self.number_of_documents = number_of_documents
        self.k1 = k1
        self.b = b

    def get_urls(self, keyword: str) -> list[str]:
        return [url for url in self._documents.keys() if keyword in self._documents[url].lower()]

    def idf(self, kw: str) -> float:
        N = self.number_of_documents
        n_kw = len(self.get_urls(kw))
        return log((N - n_kw + 0.5) / (n_kw + 0.5) + 1)

    def bm25(self, keyword: str, url: str) -> float:
        freq = self._documents[url].lower().count(keyword)
        avdl = sum(len(self._documents[u]) for u in self._documents.keys()) / self.number_of_documents
        idf_score = self.idf(keyword)
        numerator = idf_score * (freq * (self.k1 + 1))
        denominator = freq + self.k1 * (1 - self.b + self.b * len(self._documents[url]) / avdl)
        return numerator / denominator

    def search(self, query: str) -> dict[str, float]:
        normalized_query = normalize_string(query)
        keywords = normalized_query.split()
        scores = {}
        for keyword in keywords:
            if keyword in self._documents:
                for url in self.get_urls(keyword):
                    if url not in scores:
                        scores[url] = 0
                    scores[url] += self.bm25(keyword, url)
        return scores
