def log_lerp(t, a, b, max_t):
  return a * math.exp(math.log(b/a) * t / max_t)

def learning_rate_decay(
    step, lr_init, lr_final, max_steps, lr_delay_steps=0, lr_delay_mult=1
):

  if lr_delay_steps > 0 and step < lr_delay_steps:
    learning_rate = lr_init * lr_delay_mult + 0.5 * (lr_init - lr_init * lr_delay_mult) * (1 + math.cos(math.pi * step / lr_delay_steps))
  else:
    learning_rate = log_lerp(step, lr_init, lr_final, max_steps)

  return learning_rate
